### ✅ Example 1 — Abstract Class Basics

```python name=example1_abstract_basics.py
from abc import ABC, abstractmethod

# ─── ABSTRACT CLASS ─── (template / contract)
class Shape(ABC):
    """
    Abstract base class for all shapes.
    Any class that extends Shape MUST implement area() and perimeter().
    """

    def __init__(self, color="white"):
        self.color = color   # concrete attribute — shared by all shapes

    @abstractmethod
    def area(self):
        """Calculate and return the area of the shape"""
        pass   # No implementation — child must define this!

    @abstractmethod
    def perimeter(self):
        """Calculate and return the perimeter of the shape"""
        pass

    # ─── Concrete method — shared by ALL shapes ───
    def display_info(self):
        print(f"Shape    : {self.__class__.__name__}")
        print(f"Color    : {self.color}")
        print(f"Area     : {self.area():.4f} sq units")
        print(f"Perimeter: {self.perimeter():.4f} units")
        print("-" * 35)

# ─── CONCRETE CLASSES ─── (implement the contract)
class Circle(Shape):
    def __init__(self, radius, color="white"):
        super().__init__(color)
        self.radius = radius

    def area(self):           # ✅ MUST implement
        return 3.14159 * self.radius ** 2

    def perimeter(self):      # ✅ MUST implement
        return 2 * 3.14159 * self.radius

class Rectangle(Shape):
    def __init__(self, length, width, color="white"):
        super().__init__(color)
        self.length = length
        self.width  = width

    def area(self):
        return self.length * self.width

    def perimeter(self):
        return 2 * (self.length + self.width)

class Triangle(Shape):
    def __init__(self, a, b, c, color="white"):
        super().__init__(color)
        self.a, self.b, self.c = a, b, c

    def area(self):
        s = (self.a + self.b + self.c) / 2   # Heron's formula
        return (s * (s-self.a) * (s-self.b) * (s-self.c)) ** 0.5

    def perimeter(self):
        return self.a + self.b + self.c

# ─── Cannot instantiate abstract class ───
try:
    s = Shape()       # ❌ TypeError!
except TypeError as e:
    print(f"❌ {e}\n")

# ─── CAN instantiate concrete classes ───
shapes = [
    Circle(7, "Red"),
    Rectangle(10, 5, "Blue"),
    Triangle(3, 4, 5, "Green"),
]

for shape in shapes:
    shape.display_info()

# Polymorphism through abstraction
total_area = sum(s.area() for s in shapes)
print(f"Total area of all shapes: {total_area:.4f}")
```

### ✅ Example 2 — Real World: Payment Gateway Abstraction

```python name=example2_payment_abstraction.py
from abc import ABC, abstractmethod
import random

# ─── ABSTRACT BASE ─── defines the payment CONTRACT
class PaymentGateway(ABC):
    """
    Abstract class defining what ALL payment methods must support.
    Implementation details differ per payment type — hidden from the user.
    """

    def __init__(self, merchant_id):
        self.merchant_id    = merchant_id
        self.transaction_id = None

    @abstractmethod
    def connect(self):
        """Establish connection to payment provider"""
        pass

    @abstractmethod
    def charge(self, amount, currency="INR"):
        """Process the payment charge"""
        pass

    @abstractmethod
    def refund(self, transaction_id, amount):
        """Process a refund"""
        pass

    @abstractmethod
    def get_status(self, transaction_id):
        """Check payment status"""
        pass

    # ─── Concrete template method ───
    def process_payment(self, amount):
        """Template: same high-level flow for ALL gateways"""
        print(f"\n💳 Processing ₹{amount:,} via {self.__class__.__name__}")
        self.connect()
        result = self.charge(amount)
        if result:
            print(f"✅ Payment successful! TXN: {self.transaction_id}")
        else:
            print(f"❌ Payment failed!")
        return result

# ─── CONCRETE IMPLEMENTATIONS ─── (different internal workings, same interface)
class RazorpayGateway(PaymentGateway):
    def connect(self):
        # Internal: OAuth2 auth with Razorpay API — hidden from user
        print(f"   🔌 Razorpay: Authenticating with API key...")

    def charge(self, amount, currency="INR"):
        # Internal: Razorpay-specific API call — hidden
        self.transaction_id = f"rzp_{random.randint(100000,999999)}"
        print(f"   💳 Razorpay: Charging ₹{amount:,} (TXN: {self.transaction_id})")
        return True

    def refund(self, transaction_id, amount):
        print(f"   🔄 Razorpay: Refunding ₹{amount:,} for TXN {transaction_id}")
        return True

    def get_status(self, transaction_id):
        return "SUCCESS"

class StripeGateway(PaymentGateway):
    def connect(self):
        # Internal: Stripe uses different auth mechanism
        print(f"   🔌 Stripe: Connecting with Bearer token...")

    def charge(self, amount, currency="INR"):
        # Internal: Stripe charges in cents
        amount_cents = amount * 100
        self.transaction_id = f"ch_{random.randint(100000,999999)}"
        print(f"   💳 Stripe: Charging {amount_cents} paise (TXN: {self.transaction_id})")
        return True

    def refund(self, transaction_id, amount):
        print(f"   🔄 Stripe: Initiating refund for {transaction_id}")
        return True

    def get_status(self, transaction_id):
        return "SUCCEEDED"

class PayPalGateway(PaymentGateway):
    def connect(self):
        print(f"   🔌 PayPal: Getting access token via OAuth...")

    def charge(self, amount, currency="INR"):
        self.transaction_id = f"PAY-{random.randint(100000,999999)}"
        print(f"   💳 PayPal: Creating payment order ₹{amount:,}")
        return True

    def refund(self, transaction_id, amount):
        print(f"   🔄 PayPal: Processing refund via PayPal API")
        return True

    def get_status(self, transaction_id):
        return "COMPLETED"

# ─── BUSINESS CODE — doesn't care WHICH gateway is used ───
class CheckoutService:
    def __init__(self, gateway: PaymentGateway):
        self.gateway = gateway   # any gateway works — abstraction!

    def checkout(self, cart_total):
        # Same code regardless of Razorpay / Stripe / PayPal
        return self.gateway.process_payment(cart_total)

# Switch gateways without changing business code
gateways = [
    RazorpayGateway("MERCHANT_001"),
    StripeGateway("MERCHANT_001"),
    PayPalGateway("MERCHANT_001"),
]

for gateway in gateways:
    checkout = CheckoutService(gateway)
    checkout.checkout(5999)
```

### ✅ Example 3 — Abstract Class with Both Abstract and Concrete Methods

```python name=example3_mixed_methods.py
from abc import ABC, abstractmethod
from datetime import datetime

class Report(ABC):
    """
    Abstract report class.
    Concrete methods define the TEMPLATE (structure).
    Abstract methods are filled in by specific report types.
    """

    def __init__(self, title, generated_by):
        self.title        = title
        self.generated_by = generated_by
        self.generated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    # ─── ABSTRACT — subclasses define these ───
    @abstractmethod
    def fetch_data(self):
        """Fetch data from data source"""
        pass

    @abstractmethod
    def format_data(self, data):
        """Format the data for display"""
        pass

    @abstractmethod
    def get_summary(self):
        """Return a one-line summary"""
        pass

    # ─── CONCRETE — shared by ALL report types ───
    def print_header(self):
        print("=" * 60)
        print(f"  REPORT : {self.title}")
        print(f"  By     : {self.generated_by}")
        print(f"  At     : {self.generated_at}")
        print("=" * 60)

    def print_footer(self):
        print("-" * 60)
        print(f"  Summary: {self.get_summary()}")
        print("=" * 60)

    # ─── TEMPLATE METHOD PATTERN ───
    def generate(self):
        """Orchestrates: same steps for all, different implementations"""
        self.print_header()
        data = self.fetch_data()           # abstract → subclass decides
        formatted = self.format_data(data) # abstract → subclass decides
        print(formatted)
        self.print_footer()

# ─── CONCRETE REPORT TYPES ───
class SalesReport(Report):
    def __init__(self, generated_by, month):
        super().__init__("Monthly Sales Report", generated_by)
        self.month = month

    def fetch_data(self):
        # In real code: DB query. Here: dummy data
        return [
            ("Product A", 150, 75000),
            ("Product B", 80,  56000),
            ("Product C", 200, 120000),
        ]

    def format_data(self, data):
        lines = [f"\n  {'Product':<15} {'Units':>8} {'Revenue':>12}",
                 f"  {'-'*15} {'-'*8} {'-'*12}"]
        for name, units, revenue in data:
            lines.append(f"  {name:<15} {units:>8,} ₹{revenue:>10,}")
        total_rev = sum(r for _, _, r in data)
        lines.append(f"  {'-'*15} {'-'*8} {'-'*12}")
        lines.append(f"  {'TOTAL':<15} {sum(u for _,u,_ in data):>8,} ₹{total_rev:>10,}")
        return "\n".join(lines)

    def get_summary(self):
        return f"Sales report for {self.month} generated successfully"

class InventoryReport(Report):
    def __init__(self, generated_by):
        super().__init__("Inventory Status Report", generated_by)

    def fetch_data(self):
        return [
            ("Laptop",  15, "Normal"),
            ("Mouse",   3,  "LOW"),
            ("Keyboard",0,  "OUT OF STOCK"),
            ("Monitor", 22, "Normal"),
        ]

    def format_data(self, data):
        lines = [f"\n  {'Item':<15} {'Stock':>8} {'Status':>15}", f"  {'-'*40}"]
        for name, stock, status in data:
            icon = "✅" if status == "Normal" else ("⚠️" if status == "LOW" else "❌")
            lines.append(f"  {name:<15} {stock:>8} {icon} {status}")
        return "\n".join(lines)

    def get_summary(self):
        return "3 items need restocking attention"

# Generate reports — same interface, different content
print("\n")
SalesReport("Alice Johnson", "January 2026").generate()
print("\n")
InventoryReport("Bob Smith").generate()
```

### ✅ Example 4 — Multiple Abstract Classes (Interface Simulation)

```python name=example4_multiple_interfaces.py
from abc import ABC, abstractmethod

# ─── Define "interfaces" as abstract classes ───
class Flyable(ABC):
    @abstractmethod
    def fly(self):
        pass

    @abstractmethod
    def land(self):
        pass

class Swimmable(ABC):
    @abstractmethod
    def swim(self):
        pass

    @abstractmethod
    def dive(self):
        pass

class Runnable(ABC):
    @abstractmethod
    def run(self):
        pass

# ─── Classes implementing multiple "interfaces" ───
class Duck(Flyable, Swimmable, Runnable):
    """Duck can fly, swim, and run"""

    def __init__(self, name):
        self.name = name

    def fly(self):
        print(f"🦆 {self.name} is flying low over the pond")

    def land(self):
        print(f"🦆 {self.name} lands gently on water")

    def swim(self):
        print(f"🦆 {self.name} paddles gracefully")

    def dive(self):
        print(f"🦆 {self.name} dips its head underwater for food")

    def run(self):
        print(f"🦆 {self.name} waddles quickly on land")

class Eagle(Flyable, Runnable):
    """Eagle can fly and run but not swim"""

    def __init__(self, name):
        self.name = name

    def fly(self):
        print(f"🦅 {self.name} soars majestically at 3000 feet")

    def land(self):
        print(f"🦅 {self.name} swoops down and grips the branch")

    def run(self):
        print(f"🦅 {self.name} sprints with wings partially spread")

class Submarine(Swimmable):
    """Submarine can swim but not fly or run"""

    def __init__(self, name):
        self.name = name

    def swim(self):
        print(f"🚢 {self.name} moves silently through the deep")

    def dive(self):
        print(f"🚢 {self.name} descends to 500m depth")

# ─── Polymorphic usage ───
donald = Duck("Donald")
donald.fly()
donald.swim()
donald.run()

print()
simba = Eagle("Simba")
simba.fly()
simba.run()

print()
# isinstance checks on abstract classes
print(isinstance(donald, Flyable))    # True
print(isinstance(donald, Swimmable))  # True
print(isinstance(simba,  Swimmable))  # False
print(isinstance(simba,  Flyable))    # True

# Functions that accept any Flyable
def make_fly(creature: Flyable):
    creature.fly()
    creature.land()

print("\n--- All flying creatures ---")
for creature in [donald, simba]:
    make_fly(creature)
```

### ✅ Example 5 — Real World: Database Abstraction Layer

```python name=example5_database_abstraction.py
from abc import ABC, abstractmethod
from typing import List, Dict, Any

# ─── ABSTRACT DATABASE LAYER ───
class Database(ABC):
    """
    Abstract database — business code uses this interface.
    Switch MySQL ↔ PostgreSQL ↔ MongoDB without changing business logic.
    """

    def __init__(self, host, port, database_name):
        self.host          = host
        self.port          = port
        self.database_name = database_name
        self._connected    = False

    @abstractmethod
    def connect(self) -> bool:
        pass

    @abstractmethod
    def disconnect(self):
        pass

    @abstractmethod
    def execute_query(self, query: str, params: tuple = ()) -> List[Dict]:
        pass

    @abstractmethod
    def insert(self, table: str, data: Dict) -> int:
        """Returns inserted record ID"""
        pass

    @abstractmethod
    def update(self, table: str, data: Dict, condition: str) -> int:
        """Returns number of rows affected"""
        pass

    @abstractmethod
    def delete(self, table: str, condition: str) -> int:
        pass

    # ─── Concrete: shared connection check ───
    def ensure_connected(self):
        if not self._connected:
            raise ConnectionError(f"Not connected to {self.database_name}!")

    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, *args):
        self.disconnect()

# ─── MySQL Implementation ───
class MySQLDatabase(Database):
    def connect(self):
        # In real code: mysql.connector.connect(...)
        print(f"🐬 MySQL: Connecting to {self.host}:{self.port}/{self.database_name}")
        self._connected = True
        print(f"✅ MySQL connected!")
        return True

    def disconnect(self):
        print(f"🐬 MySQL: Disconnecting...")
        self._connected = False

    def execute_query(self, query, params=()):
        self.ensure_connected()
        print(f"🐬 MySQL: Executing → {query} | Params: {params}")
        return [{"id": 1, "name": "Alice"}, {"id": 2, "name": "Bob"}]

    def insert(self, table, data):
        self.ensure_connected()
        print(f"🐬 MySQL: INSERT INTO {table} {data}")
        return 42   # last insert id

    def update(self, table, data, condition):
        self.ensure_connected()
        print(f"🐬 MySQL: UPDATE {table} SET {data} WHERE {condition}")
        return 1

    def delete(self, table, condition):
        self.ensure_connected()
        print(f"🐬 MySQL: DELETE FROM {table} WHERE {condition}")
        return 1

# ─── PostgreSQL Implementation ───
class PostgreSQLDatabase(Database):
    def connect(self):
        # In real code: psycopg2.connect(...)
        print(f"🐘 PostgreSQL: Establishing connection pool to {self.host}...")
        self._connected = True
        print(f"✅ PostgreSQL connected!")
        return True

    def disconnect(self):
        print(f"🐘 PostgreSQL: Releasing connection pool...")
        self._connected = False

    def execute_query(self, query, params=()):
        self.ensure_connected()
        print(f"🐘 PostgreSQL: EXPLAIN ANALYZE → {query}")
        return [{"id": 1, "name": "Alice"}]

    def insert(self, table, data):
        self.ensure_connected()
        print(f"🐘 PostgreSQL: INSERT INTO {table} RETURNING id → {data}")
        return 101

    def update(self, table, data, condition):
        self.ensure_connected()
        print(f"🐘 PostgreSQL: UPDATE {table} SET {data} WHERE {condition}")
        return 2

    def delete(self, table, condition):
        self.ensure_connected()
        print(f"🐘 PostgreSQL: DELETE FROM {table} WHERE {condition} RETURNING *")
        return 1

# ─── BUSINESS LOGIC — works with ANY database ───
class UserRepository:
    def __init__(self, db: Database):   # accepts any Database subclass!
        self.db = db

    def create_user(self, name, email):
        with self.db:
            user_id = self.db.insert("users", {"name": name, "email": email})
            print(f"✅ User created with ID: {user_id}")
            return user_id

    def find_users(self):
        with self.db:
            return self.db.execute_query("SELECT * FROM users")

    def update_email(self, user_id, new_email):
        with self.db:
            rows = self.db.update("users", {"email": new_email}, f"id={user_id}")
            print(f"✅ Updated {rows} user(s)")

# ─── Switch databases without changing UserRepository ───
print("=" * 50)
print("Using MySQL:")
mysql_db    = MySQLDatabase("localhost", 3306, "app_db")
mysql_repo  = UserRepository(mysql_db)
mysql_repo.create_user("Alice", "alice@example.com")

print("\n" + "=" * 50)
print("Using PostgreSQL:")
pg_db   = PostgreSQLDatabase("prod-server", 5432, "app_db")
pg_repo = UserRepository(pg_db)
pg_repo.create_user("Bob", "bob@example.com")
```
